32	// hostsProxy sends requests for hosts matching globs through proxyURL, others follow the environment
33	func hostsProxy(globs []glob.Glob, proxyURL *url.URL) func(req *http.Request) (*url.URL, error) {
34		return func(req *http.Request) (*url.URL, error) {
35			for _, g := range globs {
36				if g.Match(req.URL.Host) {
37					return proxyURL, nil
38				}
39			}
40			return http.ProxyFromEnvironment(req)
41		}
42	}
