44	// Proxy returns the system proxy
45	func Proxy() func(req *http.Request) (*url.URL, error) {
46		if !setting.Proxy.Enabled {
47			return nil
48		}
49		if setting.Proxy.ProxyURL == "" {
50			return http.ProxyFromEnvironment
51		}
52		return hostsProxy(globalProxyHosts(), setting.Proxy.ProxyURLFixed)
